                        extra.append(f.read())
all_text = "\n".join(blob_parts + extra)

# exported funcs, types, consts
pat = re.compile(r'(?m)^(?:func(?: \([^)]+\))? ([A-Z][A-Za-z0-9]*)\(|type ([A-Z][A-Za-z0-9]*) |const \(\n(?:.*\n)*?|^const ([A-Z][A-Za-z0-9]*) )')
# simpler line-based
