for path, text in text_by.items():
    rel = os.path.relpath(path, root)
    for i, line in enumerate(text.splitlines(), 1):
        m = re.match(r'^func(?: \([^)]+\))? ([A-Z]\w*)\(', line)
        if m:
            idents.append((m.group(1), rel, i, "func"))
        m = re.match(r'^type ([A-Z]\w*)\b', line)
        if m:
            idents.append((m.group(1), rel, i, "type"))
        m = re.match(r'^const ([A-Z]\w*)\b', line)
        if m:
            idents.append((m.group(1), rel, i, "const"))
        m = re.match(r'^\t([A-Z]\w*)\s*=', line)
        if m and "const" in text.splitlines()[max(0,i-30):i].__repr__():
            # only inside const blocks: look backward
            prev = "\n".join(text.splitlines()[:i])
            if re.search(r'\nconst \(\s*$', prev) or re.search(r'\nconst \(\n(?:[^\n]*\n)*$', prev):
                idents.append((m.group(1), rel, i, "const"))

# count occurrences of identifier as whole word in all_text
unused = []
for name, rel, line, kind in idents:
    count = len(re.findall(r'\b'+name+r'\b', all_text))
    if count <= 1:
        unused.append((count, kind, name, f"{rel}:{line}"))

print(f"single-reference exported symbols: {len(unused)}")
for item in unused:
    print(f"{item[1]:5} {item[2]:40} {item[3]}")
